CREATE TABLE public.hei_procurement_programs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_oid text NOT NULL REFERENCES public.setc_organizations(oid), program_reference text NOT NULL, name text NOT NULL, procurement_type text NOT NULL CHECK (procurement_type IN ('GOODS','SERVICES','CONSTRUCTION','TECHNOLOGY','RESEARCH','LOGISTICS','ENERGY','HEALTH','OTHER')), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','REVIEW','APPROVED','ACTIVE','SUSPENDED','CLOSED')), governance_reference text, evidence_reference text, UNIQUE(organization_oid,program_reference));
CREATE TABLE public.hei_suppliers (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_organization_oid text NOT NULL REFERENCES public.setc_organizations(oid), supplier_reference text NOT NULL UNIQUE, qualification_state text NOT NULL DEFAULT 'IDENTIFIED' CHECK (qualification_state IN ('IDENTIFIED','DUE_DILIGENCE','QUALIFIED','APPROVED','SUSPENDED','REVOKED')), diversity_classification text, jurisdiction text, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.hei_supplier_qualifications (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_id bigint NOT NULL REFERENCES public.hei_suppliers(id) ON DELETE CASCADE, qualification_type text NOT NULL CHECK (qualification_type IN ('LEGAL','FINANCIAL','INSURANCE','CAPACITY','COMPLIANCE','CYBERSECURITY','QUALITY','DIVERSITY','SANCTIONS','OTHER')), status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','IN_PROGRESS','PASSED','PASSED_WITH_CONDITIONS','FAILED','EXPIRED','WAIVED')), valid_from timestamptz, valid_to timestamptz, reviewer_reference text, evidence_reference text, CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from));
CREATE TABLE public.hei_economic_clusters (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, cluster_reference text NOT NULL UNIQUE, name text NOT NULL, cluster_type text NOT NULL CHECK (cluster_type IN ('REGIONAL','SECTOR','DIASPORA','HBCU_HSI','RESEARCH','SUPPLY_CHAIN','OTHER')), lead_organization_oid text REFERENCES public.setc_organizations(oid), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','SUSPENDED','CLOSED')), evidence_reference text);
CREATE TABLE public.hei_economic_cluster_members (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, cluster_id bigint NOT NULL REFERENCES public.hei_economic_clusters(id) ON DELETE CASCADE, organization_oid text NOT NULL REFERENCES public.setc_organizations(oid), member_role text NOT NULL CHECK (member_role IN ('INSTITUTION','SUPPLIER','LOGISTICS_PARTNER','RESEARCH_PARTNER','FINANCE_PARTNER','PUBLIC_SECTOR','OTHER')), status text NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED','APPROVED','ACTIVE','SUSPENDED','WITHDRAWN')), evidence_reference text, UNIQUE(cluster_id,organization_oid,member_role));
CREATE TABLE public.hei_procurement_opportunities (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, procurement_program_id bigint NOT NULL REFERENCES public.hei_procurement_programs(id), opportunity_reference text NOT NULL UNIQUE, title text NOT NULL, estimated_value numeric(20,4) CHECK (estimated_value IS NULL OR estimated_value >= 0), currency_code text CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$'), sourcing_method text NOT NULL CHECK (sourcing_method IN ('OPEN_COMPETITION','INVITED_BID','RFP','RFQ','RFI','COOPERATIVE','SOLE_SOURCE','OTHER')), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','APPROVED_FOR_RELEASE','OPEN','EVALUATION','AWARDED','CANCELLED','CLOSED')), authority_reference text, evidence_reference text);
CREATE TABLE public.hei_procurement_bids (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, procurement_opportunity_id bigint NOT NULL REFERENCES public.hei_procurement_opportunities(id) ON DELETE CASCADE, supplier_id bigint NOT NULL REFERENCES public.hei_suppliers(id), bid_reference text NOT NULL UNIQUE, bid_amount numeric(20,4) CHECK (bid_amount IS NULL OR bid_amount >= 0), currency_code text CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$'), compliance_state text NOT NULL DEFAULT 'PENDING' CHECK (compliance_state IN ('PENDING','COMPLIANT','NONCOMPLIANT','CONDITIONAL')), evaluation_state text NOT NULL DEFAULT 'RECEIVED' CHECK (evaluation_state IN ('RECEIVED','UNDER_REVIEW','SHORTLISTED','SELECTED','NOT_SELECTED','WITHDRAWN')), evidence_reference text, UNIQUE(procurement_opportunity_id,supplier_id));
CREATE TABLE public.hei_procurement_awards (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, procurement_opportunity_id bigint NOT NULL REFERENCES public.hei_procurement_opportunities(id), supplier_id bigint NOT NULL REFERENCES public.hei_suppliers(id), bid_id bigint REFERENCES public.hei_procurement_bids(id), award_reference text NOT NULL UNIQUE, awarded_amount numeric(20,4) CHECK (awarded_amount IS NULL OR awarded_amount >= 0), currency_code text CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$'), status text NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED','APPROVED','CONTRACTED','ACTIVE','COMPLETED','CANCELLED','TERMINATED')), authority_reference text, contract_reference text, evidence_reference text);
CREATE TABLE public.hei_procurement_external_links (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, procurement_opportunity_id bigint NOT NULL REFERENCES public.hei_procurement_opportunities(id) ON DELETE CASCADE, link_type text NOT NULL CHECK (link_type IN ('WIM','SOURCEENERGY_GLOBAL','LOGISTICS','ERP','OTHER')), external_reference text NOT NULL, status text NOT NULL DEFAULT 'REFERENCE_ONLY' CHECK (status IN ('REFERENCE_ONLY','PUBLISHED','ACTIVE','SUSPENDED','RETIRED')), evidence_reference text, UNIQUE(procurement_opportunity_id,link_type,external_reference));
CREATE OR REPLACE FUNCTION public.hei_validate_procurement_award() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE supplier_state text; opp_state text; bid_eval text; bid_compliance text; BEGIN IF NEW.status IN ('APPROVED','CONTRACTED','ACTIVE','COMPLETED') THEN SELECT qualification_state INTO supplier_state FROM public.hei_suppliers WHERE id=NEW.supplier_id; SELECT status INTO opp_state FROM public.hei_procurement_opportunities WHERE id=NEW.procurement_opportunity_id; IF supplier_state <> 'APPROVED' THEN RAISE EXCEPTION 'approved supplier required'; END IF; IF opp_state NOT IN ('EVALUATION','AWARDED','CLOSED') THEN RAISE EXCEPTION 'procurement opportunity must be in evaluation or later'; END IF; IF NEW.bid_id IS NOT NULL THEN SELECT evaluation_state,compliance_state INTO bid_eval,bid_compliance FROM public.hei_procurement_bids WHERE id=NEW.bid_id; IF bid_eval <> 'SELECTED' OR bid_compliance <> 'COMPLIANT' THEN RAISE EXCEPTION 'selected compliant bid required'; END IF; END IF; IF NEW.authority_reference IS NULL OR btrim(NEW.authority_reference)='' THEN RAISE EXCEPTION 'procurement authority required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER hei_procurement_award_gate BEFORE INSERT OR UPDATE ON public.hei_procurement_awards FOR EACH ROW EXECUTE FUNCTION public.hei_validate_procurement_award();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['hei_procurement_programs','hei_suppliers','hei_supplier_qualifications','hei_economic_clusters','hei_economic_cluster_members','hei_procurement_opportunities','hei_procurement_bids','hei_procurement_awards','hei_procurement_external_links'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO service_role USING (true) WITH CHECK (true)',t||'_service_role_all',t); END LOOP; END $$;
COMMENT ON TABLE public.hei_suppliers IS 'Supplier registry and qualification layer; inclusion does not itself imply institutional approval or award.';
COMMENT ON TABLE public.hei_procurement_external_links IS 'Reference links to WIM, SourceEnergy Global, logistics or ERP systems; external publication does not transfer procurement authority or payment finality.';
COMMENT ON TABLE public.hei_procurement_awards IS 'Institution-controlled procurement award record; payment, custody and settlement occur in separately governed systems.';
